using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using MultiFPS;using MultiFPS.UI;using MultiFPS.Gameplay;using MultiFPS.Gameplay.RiftCombat;using ROM.UI.Sprint01;using ROM.UI.Gameplay;
namespace ROM.Progression {
public sealed class RiftLootLabelHover:MonoBehaviour,IPointerEnterHandler,IPointerExitHandler {
 public RiftGroundLoot Drop;
 public void OnPointerEnter(PointerEventData e){if(!Drop||Drop.Claimed)return;var item=Drop.Axe?RiftLootTuning.Load.Item(Drop.DefinitionId):null;string detail=Drop.Axe?"Rareza: "+Drop.RarityName+"\nRequiere nivel "+Drop.ItemLevel+"\n"+(item&&item.Weapon?item.Weapon.DamageSummary(Drop.WeaponMultiplier):""):"Oro común de El Rift";detail+="\nClic para recoger hasta "+RiftLootTuning.Load.ClickRange.ToString("0.#")+" m; al pasar cerca se recoge automáticamente.";RiftAbilityTooltip.ShowItemAtCursor(gameObject,RiftLootLabels.Title(Drop),detail,RiftLootLabels.ColorOf(Drop));}
 public void OnPointerExit(PointerEventData e)=>RiftAbilityTooltip.Hide(gameObject);
 void OnDisable()=>RiftAbilityTooltip.Hide(gameObject);
}
// One bounded, depth-tested projection layer. It never grants loot or changes pickup rules.
public sealed class RiftLootLabels:MonoBehaviour {
 sealed class Row {public RectTransform Root;public Text Text;public RiftLootLabelHover Hover;public Button Button;}
 readonly List<Row> rows=new List<Row>();Canvas canvas;RectTransform root;float next;RiftGameplayHUD hud;RiftFieldUI field;
 public static Color CommonColor {get{var entry=RiftLootTuning.Load?.DefaultTable?.Rarities?.FirstOrDefault(x=>x!=null&&x.Rarity&&x.Rarity.Kind==Rarity.Common);return entry!=null?entry.Rarity.Tint:new Color(.82f,.84f,.88f);}}
 public static Color ColorOf(RiftGroundLoot drop)=>drop.Axe?(drop.RarityColor.a>0?drop.RarityColor:CommonColor):new Color(1,.78f,.3f);
 public static string Title(RiftGroundLoot drop){if(!drop.Axe)return drop.Gold+" oro";var item=RiftLootTuning.Load.Item(drop.DefinitionId);string name=item&&item.Weapon?item.Weapon.DisplayName:"Hacha de Nertör";return drop.RarityName+" · "+name;}
 void Ensure(){if(canvas)return;var go=new GameObject("Nearby loot labels",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));go.transform.SetParent(transform,false);canvas=go.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=80;root=(RectTransform)go.transform;var scale=go.GetComponent<CanvasScaler>();scale.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scale.referenceResolution=new Vector2(1920,1080);scale.matchWidthOrHeight=1;}
 Row Create(){var go=new GameObject("Nearby loot label",typeof(RectTransform),typeof(Image),typeof(Button),typeof(RiftLootLabelHover));go.transform.SetParent(root,false);var rect=(RectTransform)go.transform;rect.sizeDelta=new Vector2(250,26);rect.pivot=new Vector2(.5f,0);go.GetComponent<Image>().color=new Color(.015f,.018f,.028f,.88f);var button=go.GetComponent<Button>();button.transition=Selectable.Transition.None;var hover=go.GetComponent<RiftLootLabelHover>();button.onClick.AddListener(()=>{if(hover.Drop&&!hover.Drop.Claimed)hover.Drop.RequestPickup();});var textGo=new GameObject("Actual loot name",typeof(RectTransform),typeof(Text),typeof(Outline));textGo.transform.SetParent(rect,false);var tr=(RectTransform)textGo.transform;tr.anchorMin=Vector2.zero;tr.anchorMax=Vector2.one;tr.offsetMin=new Vector2(8,1);tr.offsetMax=new Vector2(-8,-1);var text=textGo.GetComponent<Text>();text.font=RiftWidgets.Body?RiftWidgets.Body:Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");text.fontSize=14;text.alignment=TextAnchor.MiddleCenter;text.horizontalOverflow=HorizontalWrapMode.Overflow;text.raycastTarget=false;var shadow=textGo.GetComponent<Outline>();shadow.effectColor=new Color(0,0,0,.9f);shadow.effectDistance=new Vector2(1,-1);return new Row{Root=rect,Text=text,Hover=hover,Button=button};}
 void Hide(){foreach(var row in rows)row.Root.gameObject.SetActive(false);}
 void LateUpdate(){if(Time.unscaledTime<next)return;next=Time.unscaledTime+.08f;var player=ClientFrontend.ClientPlayerInstance;var actor=player?player.MyCharacter:null;var view=GameplayCamera._instance?GameplayCamera._instance.GetComponent<Camera>():null;if(!hud)hud=Object.FindFirstObjectByType<RiftGameplayHUD>();if(!field)field=Object.FindFirstObjectByType<RiftFieldUI>();if(!actor||!view||!hud||!hud.GetComponent<Canvas>().enabled||ClientFrontend.Pause||(field&&field.MapOpen)){Hide();return;}Ensure();var candidates=RiftGroundLoot.Active.Where(d=>d&&!d.Claimed&&d.OwnerCharacter==player.PlayerInfo.CharacterId&&d.gameObject.scene==actor.gameObject.scene&&(d.transform.position-actor.transform.position).sqrMagnitude<=144).OrderBy(d=>(d.transform.position-actor.transform.position).sqrMagnitude).ThenBy(d=>d.netId).Take(8);int count=0;var occupied=new List<Rect>();foreach(var drop in candidates){Vector3 point=drop.transform.position+Vector3.up*.45f;Vector3 screen=view.WorldToScreenPoint(point);if(screen.z<=0||screen.x<20||screen.x>Screen.width-20||screen.y<20||screen.y>Screen.height-20)continue;Vector3 delta=point-view.transform.position;if(actor.gameObject.scene.GetPhysicsScene().Raycast(view.transform.position,delta.normalized,out _,delta.magnitude-.06f,GameManager.environmentLayer,QueryTriggerInteraction.Ignore))continue;RectTransformUtility.ScreenPointToLocalPointInRectangle(root,screen,null,out var local);if(rows.Count<=count)rows.Add(Create());var row=rows[count];row.Hover.Drop=drop;row.Text.text=Title(drop);row.Text.color=ColorOf(drop);float width=Mathf.Clamp(row.Text.preferredWidth+20,64,310);Rect rect=new Rect(local.x-width*.5f,local.y,width,26);int shifts=0;while(occupied.Any(x=>x.Overlaps(rect))&&shifts++<4)rect.y+=28;if(occupied.Any(x=>x.Overlaps(rect))||rect.xMin<root.rect.xMin+8||rect.xMax>root.rect.xMax-8||rect.yMax>root.rect.yMax-8)continue;row.Root.sizeDelta=new Vector2(width,26);row.Root.anchoredPosition=new Vector2(rect.center.x,rect.yMin);row.Root.gameObject.SetActive(true);occupied.Add(rect);count++;}for(int i=count;i<rows.Count;i++)rows[i].Root.gameObject.SetActive(false);}
}
}
